def span(name, inputs):
    record = {"name": name, "inputs": inputs}
    start = time.perf_counter()
    try:
        yield record
    finally:
        record["latency_ms"] = round((time.perf_counter() - start) * 1000, 1)

with span("llm.call", {"prompt": "summarize"}) as s:
