import contextvars
from contextlib import contextmanager

class Tracer:
    def __init__(self):
        self.spans = []
        self._current = contextvars.ContextVar("current", default=None)

    @contextmanager
    def span(self, name):
        parent = self._current.get()          # active span = parent
        rec = {"name": name,
               "parent": parent["name"] if parent else None,
               "children": []}
        if parent is not None:
            parent["children"].append(rec)    # link into the tree
        self.spans.append(rec)                 # keep creation order
        token = self._current.set(rec)         # become parent for nested spans
        try:
            yield rec
        finally:
            self._current.reset(token)         # restore parent for siblings

