import contextvars, threading
from contextlib import contextmanager

current = contextvars.ContextVar("current", default=None)
SPANS = []

@contextmanager
def span(name):
    parent = current.get()
    rec = {"name": name, "parent": parent["name"] if parent else None}
    SPANS.append(rec)
    token = current.set(rec)
    try:
        yield rec
    finally:
        current.reset(token)

def run_tool(name):
    with span(name):          # expects to nest under the planner span
        pass

with span("agent.run"):
    with span("llm.plan"):
        # planner fans out tool calls onto worker threads
        threads = [threading.Thread(target=run_tool, args=(f"tool.{i}",))
                   for i in range(2)]
        for th in threads: th.start()
        for th in threads: th.join()

for s in SPANS:
    print(s["name"], "-> parent", s["parent"])

